import { useContext } from 'react';
import { FeedbackContext } from './FeedbackContext';

const FeedbackForm = () => {
  const { feedback, handleFeedbackChange } = useContext(FeedbackContext);

  return (
    <form>
      <label>
        Name:
        <input type="text" name="name" value={feedback.name} onChange={handleFeedbackChange} />
      </label>
      <label>
