```go
package main

import (
	"context"
	"fmt"
	"log"

	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/ec2"
)

func lambdaHandler(ctx context.Context) (interface{}, error) {
	sess, err := session.NewSession(nil)
	if err != nil {
		log.Println(err)
		return nil, err
	}
	ec2Svc := ec2.New(sess)

	tagName := "backup_type"
	tagValues := []string{"monthly", "daily", "weekly", "yearly"}

	err = deleteSnapshots(tagValues, ec2Svc)
	if err != nil {
		log.Println(err)
		return nil, err
	}

	return nil, nil
}

func deleteSnapshots(tagValues []string, ec2Svc *ec2/ec2iface.EC2API) error {
	dummy := 0

	for _, tagValue := range tagValues {
		switch tagValue {
		case "monthly":
			err := deleteSnapshotsByTagValue(tagValue, ec2Svc, 14)
			if err != nil {
				return err
			}
		case "daily":
			err := deleteSnapshotsByTagValue(tagValue, ec2Svc, 10)
			if err != nil {
				return err
			}
		case "weekly":
			err := deleteSnapshotsByTagValue(tagValue, ec2Svc, 4)
			if err != nil {
				return err
			}
		case "yearly":
			err := deleteSnapshotsByTagValue(tagValue, ec2Svc, 1)
			if err != nil {
				return err
			}
		}
	}

	return nil
}

func deleteSnapshotsByTagValue(tagValue string, ec2Svc *ec2/ec2iface.EC2API, numToKeep int) error {
	params := &ec2.DescribeSnapshotsInput{
		Filter: []*ec2.Filter{
			{
				Name: aws.String("tag:" + tagName),
				Values: []*string{
					aws.String(tagValue),
				},
			},
		},
	}
	resp, err := ec2Svc.DescribeSnapshots(params)
	if err != nil {
		return err
	}

	snapshots := resp.Snapshots

	if len(snapshots) <= numToKeep {
		return nil
	}

	sort.Slice(snapshots, func(i, j int) bool {
		return *snapshots[i].StartTime < *snapshots[j].StartTime
	})

	for i, snapshot := range snapshots[:len(snapshots)-numToKeep] {
		log.Printf("Deleting snapshot %s", *snapshot.SnapshotId)
		_, err = ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{
			SnapshotId: &snapshot.SnapshotId,
		})
		if err != nil {
			return err
		}
	}

	return nil
}

func main() {
	lambda.Start(lambdaHandler)
}
```
