**JavaScript (in routing.js file)**
```
// Set the fixed URLs
const urls = [
  'https://example.com/path1',
  'https://example.com/path2',
  'https://example.com/path3',
  'https://example.com/path4',
  'https://example.com/path5',
  'https://example.com/path6',
  'https://example.com/path7',
  'https://example.com/path8',
  'https://example.com/path9',
  'https://example.com/path10'
];

// Set the REST API endpoint to fetch the current counter
const apiEndpoint = 'https://example.com/counter';

// Set the initial counter value
let counter = 0;

// Fetch the initial counter value
fetch(apiEndpoint)
  .then(response => response.json())
  .then(data => {
    counter = data.value;
  })
  .catch(error => console.error(error));

// Update the counter and route the URL every 5 seconds
setInterval(() => {
  fetch(apiEndpoint)
    .then(response => response.json())
    .then(data => {
      counter = data.value;
      const targetUrl = urls[Math.floor(counter % urls.length)];
      document.getElementById('message').textContent = `Redirecting to: ${targetUrl}`;
      window.location.href = targetUrl;
    })
    .catch(error => console.error(error));
}, 5000);
```
