        loading="lazy"
      />
      <NextImage
        src={image.urls.nano}
        alt={image.description}
        width={width}
        height={height}
        objectFit="cover"
        loading="lazy"
      />
    </div>
  ));

  return (
    <div>
      <Head>
        <title>Carousel</title>
      </Head>
      <div
        style={{
          position: 'relative',
          overflow: 'hidden',
        }}
      >
        <div
          style={{
            position: 'relative',
            width: '100%',
            height: '100%',
          }}
        >
          <button
            style={{
              position: 'absolute',
              top: '50%',
              left: '50%',
              transform: 'translate(-50%, -50%)',
              cursor: 'pointer',
            }}
