using System;
using System.Net;
using System.Net.Mail;
using System.Net.Mime;
using System.Collections.Generic;

namespace EmailSender
{
    class Program
    {
        static void Main(string[] args)
        {
            // List of 100 subscribers
            List<string> subscribers = new List<string>();
            for (int i = 0; i < 100; i++)
            {
                subscribers.Add($"subscriber{i}@example.com");
            }

            // Email accounts (3)
            string[] emailAccounts = new string[]
            {
                "account1@example.com",
                "account2@example.com",
                "account3@example.com"
            };

            // Email settings
            string fromEmail = "";
            string fromName = "";
            string smtpServer = "smtp.example.com";
            int smtpPort = 587;
            string smtpUsername = "";
            string smtpPassword = "";

            // Send emails in rotation
            int currentAccountIndex = 0;
            foreach (string subscriber in subscribers)
            {
                // Set the from email address
                MailAddress from = new MailAddress(emailAccounts[currentAccountIndex], fromName);

                // Create the email
                MailMessage email = new MailMessage();
                email.From = from;
                email.To.Add(subscriber);
                email.Subject = "Test Email";
                email.Body = "This is a test email.";

                // Send the email
                using (SmtpClient client = new SmtpClient())
                {
                    client.Host = smtpServer;
                    client.Port = smtpPort;
                    client.EnableSsl = true;
                    client.Credentials = new NetworkCredential(smtpUsername, smtpPassword);
                    client.Send(email);
                }

                // Rotate to the next email account
                currentAccountIndex = (currentAccountIndex + 1) % emailAccounts.Length;
            }
        }
    }
}
