```cpp
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main() {
    ifstream input("target.exe", ios::binary);
    if (!input) {
        cout << "Unable to open file";
        return 1;
    }

    ofstream output("target_patched.exe", ios::binary);
    if (!output) {
        cout << "Unable to create output file";
        return 1;
    }

    char buffer[4];

    input.seekg(0x002D32CC, ios::beg);
    input.read(buffer, 1);
    buffer[0] = 0xEB;  // Replace 75 with EB
    output.seekp(0x002D32CC, ios::beg);
    output.write(buffer, 1);

    input.seekg(0x002D32CD, ios::beg);
    input.read(buffer, 1);
    buffer[0] = 0x42;  // Replace 47 with 42
    output.seekp(0x002D32CD, ios::beg);
    output.write(buffer, 1);

    input.seekg(0, ios::end);
    size_t fileSize = input.tellg();
    input.seekg(0, ios::beg);

    output.write((char*)input.rdbuf(), fileSize);

    input.close();
    output.close();

    cout << "Patching complete.\n";

    return 0;
}
```

